contract InvMutTest {
    C c;
    uint amt;
    bool reentered;
    bool secondPayout;

    constructor() { c = new C(address(new Log())); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function f(uint am) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (3 * am));
        require(am >= 1 ether);
        require(address(this).balance >= 3 * am);
        amt = am;
        c.Put{value: 3 * am}(0); if (__ESBMC_reverted()) return;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(!secondPayout);
    }

    receive() external payable {
        if (msg.sender == address(c)) {
            if (!reentered) {
                reentered = true;
                c.Collect(amt); if (__ESBMC_reverted()) return;
            } else {
                secondPayout = true;
            }
        }
    }
}

